#!/usr/bin/env python3
"""Smart Garbage neighbourhood dashboard. Python standard library only."""
from pathlib import Path
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import re, json, ipaddress, sys
LOG=Path(__file__).resolve().parent/"neighbourhood-live.txt"

def parse_log(text):
    events=[];previous=-1.;current=0.
    for line in text.splitlines():
        m=re.match(r"(\d+):(\d+\.\d+)\s+ID:(\d+)",line)
        if not m: continue
        t=int(m[1])*60+float(m[2])
        if previous>=0 and t<previous-1: events=[]
        previous=t;current=t
        e=None
        a=re.search(r"BIN_INIT bin=(\d+) fill=(\d+)",line)
        b=re.search(r"BIN_DEPOSIT bin=(\d+) offered=(\d+) accepted=(\d+) fill=(\d+)",line)
        c=re.search(r"BIN_RX bytes=(\d+) payload='BIN seq=(\d+) fill=(\d+)' from (\S+)",line)
        d=re.search(r"BIN_ALERT bin=(\d+) fill=(\d+) state=(CRITICAL|CLEARED)",line)
        visit=re.search(r"TRUCK_VISIT bin=(\d+) fill=(\d+)",line)
        collect=re.search(r"BIN_COLLECTION bin=(\d+) before=(\d+) removed=(\d+) fill=(\d+)",line)
        skip=re.search(r"TRUCK_SKIP bin=(\d+) fill=(\d+)",line)
        parent=re.search(r"RPL_PARENT node=(\d+) parent=(\S+)",line)
        if parent:
            try:pn=int(ipaddress.IPv6Address(parent[2]))&65535
            except ValueError:continue
            if 1<=pn<=16:e=dict(kind='parent',bin=int(parent[1]),parent=pn)
        if visit:e=dict(kind='visit',bin=int(visit[1]),fill=int(visit[2]))
        if collect:e=dict(kind='collection',bin=int(collect[1]),before=int(collect[2]),removed=int(collect[3]),fill=int(collect[4]))
        if skip:e=dict(kind='skip',bin=int(skip[1]),fill=int(skip[2]))
        if a:e=dict(kind='init',bin=int(a[1]),fill=int(a[2]))
        if b:e=dict(kind='deposit',bin=int(b[1]),offered=int(b[2]),accepted=int(b[3]),fill=int(b[4]))
        if c:
            try:node=int(ipaddress.IPv6Address(c[4]))&65535
            except ValueError:continue
            e=dict(kind='rx',bin=node,fill=int(c[3]),seq=int(c[2]),bytes=int(c[1]))
        if d:e=dict(kind='alert',bin=int(d[1]),fill=int(d[2]),status=d[3])
        if e and 2<=e['bin']<=16 and 0<=e.get('fill',0)<=100:events.append(dict(t=t,**e))
    events.sort(key=lambda e:e['t'])
    return dict(events=events,time=current)

